#!/usr/bin/env node
// Fails when src-tauri/permissions/autogenerated holds a permission file for a
// command that src-tauri/build.rs no longer lists (COMMANDS or DEV_COMMANDS).
// tauri-build writes one `<command>.toml` per listed command but never deletes
// files of removed or renamed commands, so a stale grant target would linger.
import { readdirSync, readFileSync } from "node:fs";
import { join } from "node:path";
import { pathToFileURL } from "node:url";

/** Command names in the `COMMANDS` and `DEV_COMMANDS` arrays of build.rs. */
export function listedCommands(buildRs) {
  const names = new Set();
  for (const list of ["COMMANDS", "DEV_COMMANDS"]) {
    const match = new RegExp(`const ${list}: &\\[&str\\] = &\\[([\\s\\S]*?)\\];`).exec(buildRs);
    if (!match) throw new Error(`build.rs has no ${list} array`);
    const body = match[1].replace(/\/\/[^\n]*/g, "");
    for (const [, name] of body.matchAll(/"([^"]+)"/g)) names.add(name);
  }
  return names;
}

/** Autogenerated permission files that match no listed command. */
export function stalePermissionFiles(buildRs, files) {
  const commands = listedCommands(buildRs);
  return files.filter((file) => file.endsWith(".toml") && !commands.has(file.slice(0, -".toml".length))).sort();
}

if (import.meta.url === pathToFileURL(process.argv[1] ?? "").href) {
  const dir = join("src-tauri", "permissions", "autogenerated");
  const stale = stalePermissionFiles(readFileSync(join("src-tauri", "build.rs"), "utf8"), readdirSync(dir));
  if (stale.length > 0) {
    console.error(`Permission files for commands that src-tauri/build.rs does not list (delete them):`);
    for (const file of stale) console.error(`  ${join(dir, file)}`);
    process.exit(1);
  }
  console.log("check:permissions ok");
}
